import 'package:cached_network_image/cached_network_image.dart';
import 'package:flutter/material.dart';
import 'package:intl/intl.dart' as intel;
import 'package:rowad_hrag/core/extensions/extensions.dart';
import 'package:rowad_hrag/core/widget/text_readmore_widget.dart';
import 'package:rowad_hrag/features/layout/data/models/reviews_data_model.dart';

import '../../features/product_details/domain/entities/product_details_review.dart';

class ProductReviewWidget extends StatefulWidget {
  final ProductDetailsReview review;

  const ProductReviewWidget({
    super.key,
    required this.review,
  });

  @override
  State<ProductReviewWidget> createState() => _ProductReviewWidgetState();
}

class _ProductReviewWidgetState extends State<ProductReviewWidget> {
  String formatDate(String? dateString) {
    if (dateString == null) return '—';

    try {
      final date = DateTime.parse(dateString);
      final formatter = intel.DateFormat('dd-MM-yyyy');
      return formatter.format(date);
    } catch (e) {
      return 'Invalid date';
    }
  }

  @override
  Widget build(BuildContext context) {
    return Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      textDirection: TextDirection.rtl,
      children: [
        CircleAvatar(
          radius: 30,
          backgroundImage: CachedNetworkImageProvider(
            widget.review.user.avatar ??
                "data:image/png;base64,",
          ),
        ),
        0.01.width.vSpace,
        Column(
          crossAxisAlignment: CrossAxisAlignment.end,
          children: [
            Text(
              formatDate(
                widget.review.createdAt.toString(),
              ),
              style: Theme.of(context).textTheme.labelMedium!.copyWith(
                    color: Colors.black.withAlpha(
                      80,
                    ),
                  ),
            ),
            0.01.height.hSpace,
            Text(
              widget.review.user.name,
              style: Theme.of(context).textTheme.labelLarge!.copyWith(
                    fontWeight: FontWeight.bold,
                  ),
            ),
          ],
        ),
        Expanded(
          child: TextReadmoreWidget(
            text: widget.review.comment,
          ),
        ),

        // Divider(
        //   color: Colors.grey,
        //   thickness: 1.3,
        // )
      ],
    ).hPadding(0.03.width);
  }
}
